namespace NightCodeForge.Core.Domain;

/// <summary>
/// Constants and defaults for noise-filtered Git diff and diff-stat generation.
/// </summary>
public static class GitDiffConstants
{
    /// <summary>
    /// Shared pathspec exclusion patterns applied to both full diffs and diff stat summaries.
    /// Filters out lockfiles, autogenerated designer/code-gen files, and test output/TRX reports.
    /// </summary>
    public static readonly IReadOnlyList<string> ExclusionPathspecs =
    [
        ":(exclude)package-lock.json",
        ":(exclude)pnpm-lock.yaml",
        ":(exclude)yarn.lock",
        ":(exclude)*.Designer.cs",
        ":(exclude)*.generated.cs",
        ":(exclude)*.trx",
        ":(exclude)TestResults/**",
        ":(exclude)**/TestResults/**",
        ":(exclude)bin/**",
        ":(exclude)**/bin/**",
        ":(exclude)obj/**",
        ":(exclude)**/obj/**",
        ":(exclude).vs/**",
        ":(exclude)**/.vs/**"
    ];

    public const int DefaultStatWidth = 400;
    public const int DefaultStatNameWidth = 300;
    public const int DefaultMaxStatFiles = 50;
    public const string NoChanges = "no changes";
}
